package evalartifact

// Total returns the sum of every integer, including negatives.
func Total(values []int) int {
 total := 0
 for _, value := range values {
  if value > 0 { total += value }
 }
 return total
}

package evalartifact

import "testing"

func TestTotal(t *testing.T) {
 for _, c := range []struct{values []int; want int}{
  {nil,0},{[]int{3,-5,2},0},{[]int{-4,-5},-9},{[]int{10,-4},6},
 } { if got:=Total(c.values);got!=c.want {t.Errorf("Total(%v)=%d want %d",c.values,got,c.want)} }
}

package evalartifact

import ("encoding/csv";"os";"reflect";"testing")

func TestGeneratedReport(t *testing.T) {
 f,err:=os.Open("report.csv");if err!=nil{t.Fatal(err)};defer f.Close()
 got,err:=csv.NewReader(f).ReadAll();if err!=nil{t.Fatal(err)}
 want:=[][]string{{"区县","目标","完成","差距"},{"城东","150","120","30"},{"城西","120","90","30"}}
 if !reflect.DeepEqual(got,want){t.Fatalf("report rows=%v want %v",got,want)}
}
